const FOOD_TOKENS = new Set(['bar', 'bars', 'pub', 'pubs', 'tea', 'pho', 'deli']);
export function isFood(p: Profile): boolean {
  const c = (p.tags.join(' ') + ' ' + p.subCategory).toLowerCase();
